insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'ms_art3_v1'
from (values
('117.204.b.1.A',3,'A ninth-grade-level art student sketches the wrinkles in her own hands while looking at them. The idea source is:','["direct observation", "a lucky accident", "a vocabulary list", "a scanned template"]'::jsonb,0,'Drawing what you look at directly is direct observation.','original'),
('117.204.b.1.A',3,'A student bases a mixed-media piece on a dream she had about a staircase made of water. Her concept came from:','["a ruler", "imagination", "a store catalog", "a street sign"]'::jsonb,1,'Dreams and invented images are imagination sources.','original'),
('117.204.b.1.B',4,'A critic says a painting''s use of thick, bumpy brushstrokes gives the surface a strong sense of:','["line", "space", "texture", "value"]'::jsonb,2,'Texture describes how a surface feels or appears to feel.','original'),
('117.204.b.1.B',3,'To evaluate an artist''s use of color, a student should look at hue, intensity and:','["postage", "frame", "edition number", "value"]'::jsonb,3,'Color has hue, value and intensity.','original'),
('117.204.b.1.C',4,'A quilt pattern repeats a diamond with a steady beat across its surface. This shows the principle of:','["rhythm", "emphasis", "scale", "proportion"]'::jsonb,0,'Repeated elements create visual rhythm.','original'),
('117.204.b.1.C',4,'Evaluating a poster, a student notes that one oversized red word dominates the page. This is the principle of:','["pattern", "emphasis", "unity", "balance"]'::jsonb,1,'Emphasis makes one area the focal point.','original'),
('117.204.b.1.D',4,'Two artworks use the same famous portrait pose, but one is mocking and the other respectful. Comparing them means studying their:','["frame styles", "paper sizes", "expressive properties", "shipping weights"]'::jsonb,2,'Expressive properties include tone, meaning and message.','original'),
('117.204.b.1.D',4,'A student copies a famous painting''s composition into her own piece and changes the subject to a modern topic. This is an example of:','["layering", "registration", "burnishing", "appropriation"]'::jsonb,3,'Appropriation changes existing imagery to create new meaning.','original'),
('117.204.b.2.A',3,'An artist makes a series of prints based on a theme she found while visiting her neighborhood market. Her work is built on:','["a theme from direct observation", "a worksheet answer", "a factory kit", "a stranger''s finished design"]'::jsonb,0,'Themes may come from direct observation.','original'),
('117.204.b.2.A',3,'Which pair of sources gives a student the most original starting point?','["a coloring book and a stencil", "her own sketches and a personal memory", "a poster and a logo", "a photocopy and a tracing"]'::jsonb,1,'Original sketches and memory lead to original work.','original'),
('117.204.b.2.B',3,'A sculptor builds a small model before the full piece, tests it, then makes changes. This follows the:','["guess-and-check shortcut", "skipping plan", "art-making process", "lottery process"]'::jsonb,2,'Models, testing and revising are part of the process.','original'),
('117.204.b.2.B',3,'A student designing a school logo has to meet a need: it must read clearly from far away. Meeting that need is a:','["grading rule", "filing task", "copyright fee", "design problem to solve"]'::jsonb,3,'Design starts with a problem to be solved.','original'),
('117.204.b.2.C',3,'To make a work with soft shading and light-to-dark gradations, a student would choose:','["charcoal on paper", "lump clay", "bare plaster", "wire only"]'::jsonb,0,'Charcoal blends well for tonal shading.','original'),
('117.204.b.2.C',4,'A student selects fired clay and glaze for a project because she wants a durable, water-holding vessel. This is choosing:','["materials at random", "appropriate materials for the purpose", "materials by color only", "the cheapest item"]'::jsonb,1,'Material choice should fit the artist''s purpose.','original'),
('117.204.b.2.D',4,'A student wants to build a digital collage from images found online. The safest first step is to:','["print them first", "remove the artist''s name", "find images that are in the public domain or licensed for reuse", "use any image that looks good"]'::jsonb,2,'Use public domain or licensed images.','original'),
('117.204.b.2.D',4,'A work is protected by copyright. To appropriate it legally, an artist usually needs:','["a new frame", "a bigger canvas", "no steps at all", "permission or a fair, transformative use"]'::jsonb,3,'Permission or legal transformation is needed.','original'),
('117.204.b.2.E',3,'Creating an artwork in a gallery space that surrounds the viewer, built from many objects, is called:','["installation", "contour drawing", "lithography", "still life"]'::jsonb,0,'Installation art transforms a space.','original'),
('117.204.b.2.E',3,'A group of students plans a live piece where each member adds a part to a growing display while the audience watches. This experimental form is:','["a printed poster", "collaborative performance art", "a solo drawing", "a photograph"]'::jsonb,1,'Performance and collaboration are experimental approaches.','original'),
('117.204.b.3.A',4,'Global trade and the sharing of ideas across continents have led artists to:','["stop making art", "avoid color", "blend styles from different cultures", "avoid materials"]'::jsonb,2,'Global exchange influences art.','original'),
('117.204.b.3.A',3,'Why might contemporary artists address issues like migration or climate change?','["Art must avoid current topics", "Topics are assigned by law", "Only history is allowed", "Art can respond to and reflect current events"]'::jsonb,3,'Artists often respond to the issues of their time.','original'),
('117.204.b.3.B',4,'A mural that shows a river polluted by a factory expresses an idea about:','["environmental concerns", "postal rates", "cooking times", "sports rules"]'::jsonb,0,'Art can address environmental issues.','original'),
('117.204.b.3.B',4,'Posters from a civil rights movement mostly express ideas that are:','["scientific only", "social and political", "about weather", "purely decorative"]'::jsonb,1,'Protest art expresses social and political ideas.','original'),
('117.204.b.3.C',4,'Evaluating how a dance, a song and a painting from the same festival relate to each other shows how arts:','["compete for money", "are created by accident", "connect within a society", "never overlap"]'::jsonb,2,'Arts of one society often share ideas.','original'),
('117.204.b.3.C',4,'A mask in a ritual theatre performance and a sculpture in the same culture likely share:','["a price", "a manufacturer", "a shipping route", "symbols and beliefs"]'::jsonb,3,'Shared symbols link the arts of a culture.','original'),
('117.204.b.3.D',3,'Which choice is an avocational art opportunity?','["joining a community mural club for fun", "being a paid illustrator", "serving as a museum director", "teaching college art"]'::jsonb,0,'Avocational means non-professional pursuit.','original'),
('117.204.b.3.D',3,'Comparing a career as an animator with one as a conservator, the conservator mostly:','["writes music", "preserves and repairs artworks", "sells tickets", "builds roads"]'::jsonb,1,'Conservators protect and restore artworks.','original'),
('117.204.b.4.A',4,'A student writes a response to a group sculpture project explaining the group''s goal, what each person did, and why they chose their materials. This response addresses:','["only the size", "only the cost", "purpose, process and choices", "only the date"]'::jsonb,2,'Responses explain what and why.','original'),
('117.204.b.4.A',3,'In an oral response, which statement is strongest?','["It turned out good.", "It was nice.", "Everyone liked it.", "Our group used overlapping lines to create the sense of motion we wanted."]'::jsonb,3,'Specific language shows understanding.','original'),
('117.204.b.4.B',4,'A critique of a portfolio that moves from description to analysis to interpretation to judgment is using a:','["structured method of critique", "random opinion", "quick vote", "guessing routine"]'::jsonb,0,'Critique follows a method.','original'),
('117.204.b.4.B',4,'When critiquing a portfolio, evidence of growth is best found by:','["counting pages", "comparing early and late works", "measuring covers", "checking folder color"]'::jsonb,1,'Growth shows in comparison over time.','original'),
('117.204.b.4.C',3,'Visiting an artist''s open studio is a way to investigate original art:','["on a phone case", "on a worksheet", "in a venue outside the classroom", "through a test"]'::jsonb,2,'Studios and galleries are outside venues.','original'),
('117.204.b.4.C',3,'Which is a venue outside school where students can explore original artworks?','["a cafeteria tray", "a locker", "a gym floor", "a public sculpture park"]'::jsonb,3,'Parks and museums hold original art.','original'),
('117.204.b.4.D',3,'At an exhibition opening, proper behavior includes:','["asking before taking photos and keeping your hands off the art", "moving the labels", "touching the paint", "taking a piece home"]'::jsonb,0,'Respect the work, the rules and the space.','original'),
('117.204.b.4.D',3,'Before hanging a show in the school library, the students should:','["leave it unlabeled", "plan spacing, labels and lighting", "stack them on the floor", "tape works at random"]'::jsonb,1,'Good exhibition practice includes planning for display.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
